/**
 * The bikini bottom's outline traced onto her skin (src/sarahlab/bikiniBottomStencil.ts, generated by
 * scripts/traceBikiniBottom.mjs from the Meshy brief fitted into her body file): it decodes to the body it was traced
 * on and to nothing else, every value stays within its reach, on a half-millimetre step and on its own side of the
 * line, and what it covers is a bikini bottom's worth of her skin.
 */
import { describe, expect, it } from 'vitest';
import { BIKINI_BOTTOM_STENCIL, bikiniBottomField } from '../src/sarahlab/bikiniBottomStencil';

describe("the bikini bottom's outline, traced onto her skin (Joshua, 2026-11-11)", () => {
  it('decodes to the body it was traced on, and to nothing else', () => {
    expect(bikiniBottomField(5)).toBeNull();
    expect(bikiniBottomField(BIKINI_BOTTOM_STENCIL.vertices - 1)).toBeNull();
    const field = bikiniBottomField(BIKINI_BOTTOM_STENCIL.vertices)!;
    expect(field).toBeInstanceOf(Float32Array);
    expect(field).toHaveLength(115710);
    // decoded once: every call, with her count or none, hands back the same array
    expect(bikiniBottomField()).toBe(field);
  });

  it('keeps every value within reach and on a step, stores exactly its entries, and none on the line itself', () => {
    const field = bikiniBottomField()!;
    const { far, step, entries } = BIKINI_BOTTOM_STENCIL;
    const bare = Math.fround(-far);
    let outOfReach = 0, offStep = 0, stored = 0, onLine = 0, inside = 0;
    for (const f of field) {
      if (!(f >= -Math.fround(far) && f <= Math.fround(far))) outOfReach++;
      if (f !== bare) { stored++; if (Math.abs(f / step - Math.round(f / step)) > 1e-3) offStep++; }
      if (f === 0) onLine++;
      if (f > 0) inside++;
    }
    expect(outOfReach).toBe(0);
    expect(offStep).toBe(0);
    expect(stored).toBe(entries);
    expect(onLine).toBe(0);
    // a bikini bottom's worth of her skin: thousands of vertices, neither a speck nor her whole trunk
    expect(inside).toBeGreaterThan(2500);
    expect(inside).toBeLessThan(9000);
  });
});
